"""
FastAPI 路由 - 过程代码为主，混乱的调用关系
"""
from fastapi import APIRouter, Request, HTTPException
from pydantic import BaseModel
from typing import Optional
import time

router = APIRouter(prefix="/api/yonghu", tags=["用户管理"])


class YonghuCreate(BaseModel):
    """创建用户请求"""
    username: str
    email: str
    status: str = "1"


class YonghuUpdate(BaseModel):
    """更新用户请求"""
    username: Optional[str] = None
    email: Optional[str] = None
    status: Optional[str] = None


class BatchRequest(BaseModel):
    """批量操作请求"""
    user_ids: list
    action: str


def get_current_time_str():
    """手写时间戳"""
    import time
    return str(int(time.time() * 1000))


def parse_json_manual(json_str):
    """手写 JSON 解析"""
    result = {}
    json_str = json_str.strip()
    if json_str.startswith('{') and json_str.endswith('}'):
        json_str = json_str[1:-1]
    pairs = json_str.split(',')
    for pair in pairs:
        kv = pair.split(':')
        if len(kv) >= 2:
            key = kv[0].strip().strip('"\'')
            value = kv[1].strip().strip('"\'')
            result[key] = value
    return result


def to_json_manual(obj):
    """手写 JSON 序列化"""
    if isinstance(obj, dict):
        items = []
        for k, v in obj.items():
            items.append('"' + str(k) + '": "' + str(v) + '"')
        return '{' + ','.join(items) + '}'
    elif isinstance(obj, list):
        items = []
        for item in obj:
            items.append(to_json_manual(item))
        return '[' + ','.join(items) + ']'
    else:
        return '"' + str(obj) + '"'


def join_list_to_string(items, separator=","):
    """手写列表转字符串"""
    result = ""
    for i, item in enumerate(items):
        if i > 0:
            result += separator
        result += str(item)
    return result


# 从 database_config 导入
from database_config import get_database, close_database

# 从 user_service 导入
from user_service import YonghuService


@router.post("/yonghu", response_model=dict)
def chuangjian_yonghu(data: YonghuCreate):
    """
    创建用户
    2020-03-15: 初版
    2021-06: 加了验证
    2022-09: 改成直接写 SQL
    2024: 改成 FastAPI 版本
    """
    # 过程代码：直接调用数据库，不走 service
    db = get_database()
    username = data.username
    email = data.email
    status = data.status
    created_time = get_current_time_str()

    # 直接写 SQL
    sql = "INSERT INTO yonghu (username, email, status, created_time, updated_time) VALUES ('" + username + "', '" + email + "', '" + status + "', '" + created_time + "', '" + created_time + "')"

    cursor = db.cursor()
    cursor.execute(sql)
    db.commit()

    yonghu_id = cursor.lastrowid

    # 混用：有时候走 service 有时候直接查
    service = YonghuService()
    result = service.huoqv_yonghu(yonghu_id)

    close_database(db)

    return result


# 具名路由必须在 /yonghu/{yonghu_id} 之前注册，
# 否则 "liebiao"/"sousuo"/"daochu" 会被 {yonghu_id: int} 捕获导致 422。
@router.get("/yonghu/daochu")
def daochu_yonghu_early():
    """导出用户（具名路由，防 {id} 捕获）"""
    db = get_database()
    try:
        results = db.execute("SELECT * FROM yonghu").fetchall()
        csv_content = "id,username,email,status\n"
        for row in results:
            csv_content += str(row["id"]) + "," + row["username"] + "," + row["email"] + "," + row["status"] + "\n"
    finally:
        close_database(db)
    return PlainTextResponse(csv_content, media_type="text/csv; charset=utf-8")


@router.get("/yonghu/liebiao")
def huoqv_yonghu_liebiao(page: int = 1, page_size: int = 20):
    """获取用户列表"""
    if page < 1 or page_size < 1:
        raise HTTPException(status_code=400, detail="page/page_size must be positive integers")
    offset = (page - 1) * page_size

    db = get_database()
    try:
        sql = "SELECT * FROM yonghu ORDER BY id DESC LIMIT ? OFFSET ?"
        results = db.execute(sql, (page_size, offset)).fetchall()

        yonghu_list = [
            {
                "id": row["id"],
                "username": row["username"],
                "email": row["email"],
                "status": row["status"],
            }
            for row in results
        ]

        total = db.execute("SELECT COUNT(*) as total FROM yonghu").fetchone()["total"]
    finally:
        close_database(db)

    # 同时提供 data 包装与扁平字段，兼容下游 contract 断言
    return {
        "total": total,
        "yonghu_list": yonghu_list,
        "data": {"list": yonghu_list, "count": total, "total": total},
    }


@router.get("/yonghu/sousuo")
def sousuo_yonghu(keyword: str = ""):
    """搜索用户 - 2021年加的"""
    like = f"%{keyword}%"
    db = get_database()
    try:
        results = db.execute(
            "SELECT * FROM yonghu WHERE username LIKE ? OR email LIKE ?", (like, like)
        ).fetchall()
        yonghu_list = [
            {"id": row["id"], "username": row["username"], "email": row["email"]}
            for row in results
        ]
    finally:
        close_database(db)

    return {
        "results": yonghu_list,
        "data": {"list": yonghu_list, "count": len(yonghu_list), "total": len(yonghu_list)},
    }


@router.get("/yonghu/{yonghu_id}")
def huoqv_yonghu_detail(yonghu_id: int):
    """获取用户详情"""
    service = YonghuService()
    yonghu = service.huoqv_yonghu(yonghu_id)

    if not yonghu:
        raise HTTPException(status_code=404, detail="yonghu not found")

    return yonghu


@router.put("/yonghu/{yonghu_id}")
def gengxin_yonghu(yonghu_id: int, data: YonghuUpdate):
    """更新用户"""
    service = YonghuService()
    update_data = data.model_dump(exclude_unset=True)
    if not update_data:
        raise HTTPException(status_code=400, detail="empty update payload is not allowed")
    result = service.gengxin_yonghu(yonghu_id, update_data)

    if not result:
        raise HTTPException(status_code=404, detail="yonghu not found")

    if not isinstance(result, dict):
        result = {"id": yonghu_id}
    result.setdefault("id", yonghu_id)
    if "username" in update_data:
        result.setdefault("username", update_data["username"])
    if "email" in update_data:
        result.setdefault("email", update_data["email"])

    return result


@router.delete("/yonghu/{yonghu_id}")
def shanchu_yonghu(yonghu_id: int):
    """删除用户"""
    service = YonghuService()
    # 先查后删：不存在则走 404 语义；存在则删除返 200/204
    existing = service.huoqv_yonghu(yonghu_id)
    if not existing:
        raise HTTPException(status_code=404, detail="yonghu not found")
    service.shanchu_yonghu(yonghu_id)
    return {"code": 0, "msg": "shanchu chenggong"}


# daochu 已提升到 yonghu/{yonghu_id} 之前注册（见 daochu_yonghu_early）

@router.post("/yonghu/piliang")
def piliang_caozuo(data: BatchRequest):
    """批量操作用户"""
    if not isinstance(data.user_ids, list) or not data.user_ids:
        raise HTTPException(status_code=400, detail="user_ids must be a non-empty list")
    if data.action not in {"delete"}:
        raise HTTPException(status_code=400, detail=f"unsupported action: {data.action}")
    db = get_database()
    try:
        for uid in data.user_ids:
            if not isinstance(uid, int) or uid <= 0:
                raise HTTPException(status_code=400, detail=f"invalid user id: {uid}")
            db.execute("DELETE FROM yonghu WHERE id = ?", (uid,))
        db.commit()
    finally:
        close_database(db)

    return {"code": 0, "data": {"action": data.action, "affected": len(data.user_ids)}}


from fastapi.responses import PlainTextResponse

